window.piResendAirbnbOtp = async function (asEmail) {
  var id = window._piAirbnbLoginId;
  if (!id) { msg('No active Airbnb connect — click Connect Airbnb', false); return; }
  msg(asEmail ? 'Asking Airbnb to email a new code…' : 'Resending code…', true);
  try {
    var res = await fetch('/api/platform-invoices/sessions/airbnb/login/' + encodeURIComponent(id) + '/resend', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ channel: asEmail ? 'email' : 'sms' })
    });
    var j = await res.json();
    if (!res.ok) throw new Error((j && j.error) || 'Resend failed');
    if (j.job) piRenderAirbnbConnect(j.job);
    msg(j.job && j.job.hint ? j.job.hint : (j.resent ? 'Code resent — check email' : 'Could not click Resend on Airbnb page'), !!j.resent);
  } catch (e) { msg(e.message || String(e), false); }
};
